// 采集 RSS → feed 适配 → news-sync 主流程(去重/限量/发布/告警均在 services/news-sync 内)
// 沙箱无全局 fetch 且 undici 在冻结原型下会崩,用 node:http(s) 垫片注入 fetchImpl(忽略 signal,自带 20s 超时)
const fetchImpl = (() => {
  const http = require('node:http'), https = require('node:https'), { URL } = require('node:url');
  return (url, opt = {}) => new Promise((resolve, reject) => {
    const u = new URL(url);
    const req = (u.protocol === 'http:' ? http : https).request(u, { method: opt.method || 'GET', headers: opt.headers }, res => {
      const bufs = [];
      res.on('data', d => bufs.push(d));
      res.on('end', () => {
        const t = Buffer.concat(bufs).toString('utf8');
        resolve({
          ok: res.statusCode >= 200 && res.statusCode < 300, status: res.statusCode,
          headers: { getSetCookie: () => res.headers['set-cookie'] || [], get: n => res.headers[String(n).toLowerCase()] },
          text: async () => t, json: async () => JSON.parse(t)
        });
      });
    });
    req.on('error', reject);
    req.setTimeout(20000, () => req.destroy(new Error('request timeout')));
    if (opt.body) req.write(opt.body);
    req.end();
  });
})();
// 任务运行器子进程不透传容器 env;经 n8n $env 读取(实例需 N8N_BLOCK_ENV_ACCESS_IN_NODE=false)
const env = Object.fromEntries(['NEWS_RSS_URL','NEWS_PORTAL_PUBLISH_URL','NEWS_PORTAL_TOKEN','NEWS_PORTAL_USER','NEWS_PORTAL_PASS','NEWS_PORTAL_CITYID','NEWS_PORTAL_TYPEID','NEWS_ALERT_BOT_TOKEN','NEWS_ALERT_CHAT_ID','NEWS_ALERT_API_BASE','NEWS_SYNC_SEEN_FILE','NEWS_SYNC_MAX_PER_RUN'].map(k => [k, $env[k]]).filter(([, v]) => v != null && v !== ''));
const { rssToItems } = require('/news-sync/src/feed.js');
const { main } = require('/news-sync/src/cli.js');
const res = await fetchImpl(env.NEWS_RSS_URL);
if (!res.ok) throw new Error(`RSS HTTP ${res.status}`);
const items = rssToItems(await res.text());
const stats = await main({ env, readInput: () => JSON.stringify(items), fetchImpl });
if (stats.failed || stats.alertFailed) throw new Error(`news-sync failures: ${JSON.stringify(stats)}`);
return [{ json: { source: 'news-sync', collected: items.length, ...stats } }];
